# Model: redirections are applied left to right on a table of file descriptors.
def run(redirs):
    fd = {1: "terminal", 2: "terminal"}
    for r in redirs:
        kind, a, b = r
        if kind == "file":      # N> file : fd N now points at the file
            fd[a] = b
        else:                   # N>&M : fd N copies where fd M points NOW
            fd[a] = fd[b]
    return fd

cases = {
    "> file 2>&1": [("file", 1, "file"), ("dup", 2, 1)],
    "2>&1 > file": [("dup", 2, 1), ("file", 1, "file")],
}
for text, redirs in cases.items():
    fd = run(redirs)
    print(text.ljust(12), "stdout ->", fd[1], "| stderr ->", fd[2])

# Idempotent vs blind append: run each twice and compare the final state.
def blind_append(lines, line):
    lines.append(line)
    return True

def ensure_line(lines, line):
    if line in lines:           # check first, act only if needed
        return False
    lines.append(line)
    return True

for name, fn in [("blind append", blind_append), ("ensure line", ensure_line)]:
    conf = ["a=1"]
    changes = 0
    for run in (1, 2, 3):
        if fn(conf, "b=2"):
            changes += 1
    print(name.ljust(13), "changes:", changes, "final:", conf)
